# Load current grids to see what we have
import os, re

def load_grids():
    session_dir = os.environ.get('RLM_SESSION_DIR', '')
    if not session_dir:
        return {}
    sessions_file = os.path.join(session_dir, '../../sessions/', os.path.basename(session_dir) + '.jsonl')
    try:
        with open(sessions_file, 'r') as f:
            content = f.read().replace('\\n', '\n')

        G = {}
        for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
            k, h, w = m[1], int(m[2]), int(m[3])
            rows = [r.split() for r in content[m.end():].split('\n')[:h]]
            if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
                G[k] = [[int(x) for x in r] for r in rows]
        return G
    except Exception as e:
        print(f"Error: {e}")
        return {}

G = load_grids()
print("Loaded keys:", sorted(G.keys()))
for k, v in G.items():
    print(f"{k}: {len(v)}x{len(v[0]) if v else 0}")

